/// @see vce_set_specific_engine_request_cb()
final class vce_request_callback_s extends ffi.Struct {
  /// < Version
  @ffi.Int()
  external int version;

  /// < Called when the engine service user requests the basic information of VC engine
  external vce_get_info_cb get_info;

  /// < Get recording format
  external vce_get_recording_format_cb get_recording_format;

  /// < Foreach language list
